    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        int n = s.length();

        // For any tree, removing one edge creates components of sizes x and n-x.
        // Therefore possible sizes form a symmetric set:
        // s[i-1] == s[n-i-1] for all i.
        // Also size n is impossible, so last character must be 0.
        if (s.charAt(n - 1) != '0') {
            System.out.println("No");
            return;
        }

        for (int i = 1; i <= n; i++) {
            if (s.charAt(i - 1) != s.charAt(n - i - 1 < 0 ? 0 : n - i - 1 + 0)) {
                // safer to write directly with indices:
            }
        }
        for (int i = 1; i <= n - 1; i++) {
            if (s.charAt(i - 1) != s.charAt(n - i - 1)) {
                System.out.println("No");
                return;
            }
        }

        // It is also necessary that there is at least one '1', otherwise impossible for n>=2
        // because every tree edge removal yields some component sizes.
        boolean any = false;
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') any = true;
        if (!any) {
            System.out.println("No");
            return;
        }

        // Standard constructive solution:
        // Consider positions 1..n around a cycle notionally.
        // Since s[n]=0 and symmetry holds, if s[n-1]=1 then we can construct.
        // More generally, find a position rt with s[rt-1]=='1' and s[rt]=='0' in circular sense.
        // Because s[n-1]=0 and there exists some '1', such a boundary exists.
        int rt = -1; // 1-based
        for (int i = 1; i <= n; i++) {
            char cur = s.charAt(i - 1);
            char nxt = s.charAt(i % n);
            if (cur == '1' && nxt == '0') {
                rt = i;
                break;
            }
        }

        if (rt == -1) {
            System.out.println("No");
            return;
        }

        System.out.println("Yes");

        // Build edges.
        // For vertices in circular order starting from rt+1, connect runs ending at positions with '1' to rt.
        // Between consecutive non-special vertices connect as a path.
        List<int[]> edges = new ArrayList<>();
        int last = rt;
        for (int k = 1; k < n; k++) {
            int v = ((rt + k - 1) % n) + 1; // rt+1, rt+2, ..., wrapping
            int prevPos = ((v - 2 + n) % n) + 1; // v-1 circular, 1-based
            if (s.charAt(prevPos - 1) == '1') {
                edges.add(new int[]{rt, v});
                last = v;
            } else {
                edges.add(new int[]{last, v});
                last = v;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int[] e : edges) {
            sb.append(e[0]).append(' ').append(e[1]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

